import math
import torch

def run(pooled, indices, output_size):
    return torch.ops.aten.max_unpool2d(pooled, indices, output_size)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    shape = ctx["indices__shape"]
    output_size = ctx["output_size"]
    upper = output_size[-2] * output_size[-1]
    values_per_slice = math.prod(shape[-2:])
    if values_per_slice > upper:
        raise ValueError("max_unpool2d requires unique indices within output_size")
    step = max(upper // values_per_slice, 1)
    base = torch.arange(
        values_per_slice,
        dtype=_dtype_from_context(ctx, "indices"),
        device=device,
    ) * step
    indices = base.reshape(1, 1, *shape[-2:]).expand(shape).clone()
    return {"indices": indices}
